import * as d3 from 'd3';
import { Sel, drawLabel, drawArrow, fmtNum } from '../primitives';
import { ComputationGraph } from '../../graph/types';
import { ComponentDef } from '../../components/types';

export interface EmbeddingStep {
  id: number;
  label: string;
  shortLabel: string;
  formula: string;
  explanation: string;
  code: { title: string; lines: string[] };
  svgGroup: string;
  color: string;
  fill: string;
}

export const EMBEDDING_STEPS: EmbeddingStep[] = [
  {
    id: 1,
    label: 'Token IDs → Embedding Lookup',
    shortLabel: 'Token Lookup',
    formula: 'e = E[token_id]',
    explanation:
      'Each integer token ID indexes into the embedding matrix E ∈ ℝ^(vocab × d_model), ' +
      'extracting a dense row vector. This is a simple gather — no multiply, just a table lookup. ' +
      'The embedding matrix is the largest parameter block in small models (vocab × d_model ≈ 16M for vocab=32k, d=512).',
    code: {
      title: 'Token Embedding Lookup',
      lines: [
        'self.embed = nn.Embedding(vocab_size, d_model)',
        '# forward:',
        'e = self.embed(token_ids)  # [B, seq, d_model]',
      ],
    },
    svgGroup: 'step-token',
    color: '#16a34a',
    fill: '#dcfce7',
  },
  {
    id: 2,
    label: 'Scale by √d_model',
    shortLabel: 'Scale',
    formula: 'e = e × √d_model',
    explanation:
      'In "Attention Is All You Need", weights are initialized with variance ~1/d_model. ' +
      'Multiplying by √d_model brings the embedding vectors to O(1) magnitude, ' +
      'matching the amplitude of the sinusoidal positional encoding that is added next. ' +
      'This prevents the PE from being swamped by very small embedding values.',
    code: {
      title: 'Embedding Scale',
      lines: [
        'import math',
        'scale = math.sqrt(d_model)',
        'e = e * scale  # [B, seq, d_model]',
      ],
    },
    svgGroup: 'step-scale',
    color: '#d97706',
    fill: '#fef3c7',
  },
  {
    id: 3,
    label: 'Add Positional Encoding (Sinusoidal / Learned)',
    shortLabel: 'Pos Encoding',
    formula: 'x = e + PE(pos)',
    explanation:
      'Transformers have no recurrence, so position must be injected explicitly. ' +
      'Sinusoidal PE: PE(pos, 2i) = sin(pos/10000^(2i/d_model)), PE(pos, 2i+1) = cos(…). ' +
      'Learned PE: trainable matrix P ∈ ℝ^(max_seq × d_model). ' +
      'Both add position info before the first attention layer. ' +
      'Used in BERT, GPT-2, T5-relative. RoPE/ALiBi skip this step entirely.',
    code: {
      title: 'Sinusoidal Positional Encoding',
      lines: [
        '# Pre-computed sinusoidal table',
        'pos = torch.arange(seq_len).unsqueeze(1)  # [seq, 1]',
        'dim = torch.arange(0, d_model, 2)         # [d/2]',
        'angles = pos / 10000 ** (dim / d_model)',
        'PE = torch.zeros(seq_len, d_model)',
        'PE[:, 0::2] = torch.sin(angles)',
        'PE[:, 1::2] = torch.cos(angles)',
        'x = e + PE  # [B, seq, d_model]',
      ],
    },
    svgGroup: 'step-pe',
    color: '#2563eb',
    fill: '#dbeafe',
  },
  {
    id: 4,
    label: 'RoPE: Rotate Q/K in Attention (Not Here)',
    shortLabel: 'RoPE / ALiBi',
    formula: 'q_rot = q·cos(mθ) − rotate_half(q)·sin(mθ)',
    explanation:
      'RoPE (Rotary Position Embedding) encodes position inside the attention computation, not at the embedding layer. ' +
      'It rotates Q and K vectors in d/2 2D planes by an angle proportional to absolute position. ' +
      'The result: attention scores depend only on relative position (q_m · k_n = f(m-n)), ' +
      'with full generalization to longer sequences. Default in Llama, Mistral, Qwen, Gemma, DeepSeek. ' +
      'ALiBi instead subtracts a linear bias from attention logits based on distance.',
    code: {
      title: 'RoPE Application (inside Attention)',
      lines: [
        '# θ_i = 1 / 10000^(2i/d_head)',
        'def rotate_half(x):',
        '    x1, x2 = x[..., ::2], x[..., 1::2]',
        '    return torch.stack([-x2, x1], dim=-1).flatten(-2)',
        '',
        'def apply_rope(x, cos, sin):',
        '    return x * cos + rotate_half(x) * sin',
        '',
        '# Applied to Q and K, not to embeddings',
        'q = apply_rope(q, cos[pos], sin[pos])',
        'k = apply_rope(k, cos[pos], sin[pos])',
      ],
    },
    svgGroup: 'step-rope',
    color: '#7c3aed',
    fill: '#ede9fe',
  },
];

// ─────────────────────────────────────────────────────────────────────────────
// Token definitions — fixed ID so same token always maps to same row
// ─────────────────────────────────────────────────────────────────────────────

interface TokenDef {
  word: string;
  id: number;       // vocab index (row in E)
  color: string;    // unique color for this token's lookup path
  accent: string;   // lighter shade for fill
}

const TOKENS: TokenDef[] = [
  { word: 'The',  id: 2,  color: '#2563eb', accent: '#dbeafe' },
  { word: 'cat',  id: 5,  color: '#d97706', accent: '#fef3c7' },
  { word: 'sat',  id: 8,  color: '#dc2626', accent: '#fee2e2' },
  { word: 'cat',  id: 5,  color: '#d97706', accent: '#fef3c7' }, // same as token[1]
];

// ─────────────────────────────────────────────────────────────────────────────
// Main render
// ─────────────────────────────────────────────────────────────────────────────

export function renderEmbeddingDetailed(
  g: d3.Selection<SVGGElement, unknown, null, undefined>,
  params: Record<string, number | string>,
  _meta: ComponentDef,
  _graph: ComputationGraph
): { width: number; height: number; steps: EmbeddingStep[] } {
  const posEncoding = String(params['pos_encoding'] ?? 'rope');

  const vocabSize = Number(params['vocab_size']) || 32000;
  const dModel    = Number(params['d_model']) || 512;
  const seqLen    = Number(params['seq_len']) || 128;

  const W = 720;
  const cx = W / 2;
  let y = 28;

  // ── Title ─────────────────────────────────────────────────────────────────
  lbl(g, cx, y, 'Embedding Layer', { size: 15, weight: '700', color: 'var(--text)' });
  y += 18;
  lbl(g, cx, y, `pos_encoding = ${posEncoding}`, { size: 10, color: 'var(--text-muted)' });
  y += 22;

  // ── Parameter mapping ────────────────────────────────────────────────────
  const pmGrp = g.append('g').attr('transform', `translate(${cx - 220}, ${y})`);
  pmGrp.append('rect').attr('width', 440).attr('height', 48).attr('rx', 6)
    .attr('fill', 'var(--surface)').attr('stroke', 'var(--border)').attr('stroke-width', 1);
  lbl(pmGrp as Sel, 8, 14, 'Parameters →', { size: 8, weight: '700', color: 'var(--text-muted)' });

  const pmItems = [
    { label: `vocab_size = ${vocabSize}`, dim: 'E rows', color: '#16a34a' },
    { label: `d_model = ${dModel}`, dim: 'E cols / output dim', color: '#1976d2' },
    { label: `seq_len = ${seqLen}`, dim: 'seq axis', color: '#7c3aed' },
  ];
  pmItems.forEach((item, i) => {
    const px = 10 + i * 148;
    pmGrp.append('rect').attr('x', px).attr('y', 22).attr('width', 140).attr('height', 18).attr('rx', 4)
      .attr('fill', hexWithAlpha(item.color, 0.08)).attr('stroke', item.color).attr('stroke-width', 1);
    lbl(pmGrp as Sel, px + 6, 31, item.label, { size: 7, weight: '600', color: item.color, font: 'monospace', anchor: 'start' });
    lbl(pmGrp as Sel, px + 6, 38, `→ ${item.dim}`, { size: 6, color: item.color, anchor: 'start' });
  });
  y += 56;

  // ── Step 1: Token IDs + matrix lookup ────────────────────────────────────
  const secLookup = g.append('g').attr('class', 'step-node step-token').attr('data-step', '1');
  const step1LabelY = y;
  y += 100;

  const matCols  = 6;
  const matRows  = 12;
  const cellW    = 31;
  const cellH    = 20;
  const matW     = matCols * cellW;
  const matH     = matRows * cellH;
  const matX     = 30;
  const matY     = y;
  const tokenAreaX = matX + matW + 90;
  const tokenAreaY = matY;

  drawEmbeddingMatrixWithData(
    secLookup as Gsel, matX, matY, matCols, matRows, cellW, cellH, TOKENS, vocabSize, dModel,
  );
  drawTokenLookup(
    secLookup as Gsel, g,
    tokenAreaX, tokenAreaY,
    matX, matY, cellW, cellH,
    TOKENS,
  );
  lbl(secLookup, cx, step1LabelY, 'Step 1 — Token ID → Embedding Matrix Lookup', {
    size: 10, weight: '700', color: '#16a34a',
  });

  y += matH + 40;

  // ── Step 2: Scale ─────────────────────────────────────────────────────────
  const secScale = g.append('g').attr('class', 'step-node step-scale').attr('data-step', '2');
  arrowDown(g, cx, y - 14, y - 2);
  roundBox(
    secScale as Sel, cx - 130, y, 260, 36,
    'Step 2 — Scale ×√d_model', 'e = e × √d_model', '#d97706', '#fef3c7',
  );
  y += 52;

  // ── Step 3: variant-specific PE section ──────────────────────────────────
  let variantStep: EmbeddingStep;
  switch (posEncoding) {
    case 'sinusoidal': {
      variantStep = EMBEDDING_STEPS[2];
      const sec = g.append('g').attr('class', 'step-node step-pe').attr('data-step', '3');
      arrowDown(g, cx, y - 14, y - 2);
      y = drawSinusoidalPESection(g, sec, cx, y, dModel, seqLen);
      break;
    }
    case 'learned': {
      variantStep = LEARNED_PE_STEP;
      const sec = g.append('g').attr('class', 'step-node step-pe-learned').attr('data-step', '3');
      arrowDown(g, cx, y - 14, y - 2);
      y = drawLearnedPESection(g, sec, cx, y, dModel, seqLen);
      break;
    }
    case 'rope': {
      variantStep = ROPE_STEP;
      const sec = g.append('g').attr('class', 'step-node step-rope').attr('data-step', '3');
      arrowDown(g, cx, y - 14, y - 2);
      y = drawRoPESection(g, sec, cx, y, dModel);
      break;
    }
    case 'alibi': {
      variantStep = ALIBI_STEP;
      const sec = g.append('g').attr('class', 'step-node step-alibi').attr('data-step', '3');
      arrowDown(g, cx, y - 14, y - 2);
      y = drawALiBiSection(sec, cx, y);
      break;
    }
    default: {
      variantStep = NO_PE_STEP;
      const sec = g.append('g').attr('class', 'step-node step-no-pe').attr('data-step', '3');
      arrowDown(g, cx, y - 14, y - 2);
      y = drawNoPESection(g, sec, cx, y);
      break;
    }
  }

  // ── Output: 3D tensor ─────────────────────────────────────────────────────
  arrowDown(g, cx, y - 14, y - 2);
  lbl(g, cx, y, 'Output Embeddings', { size: 10, weight: '600', color: '#16a34a' });
  y += 18;
  draw3DTensor(g, cx - 99, y, 198, 88, 24, 'x', `[B, ${seqLen}, ${dModel}]`, '#16a34a');
  y += 88 + 24 + 34;

  // Param / FLOPs
  lbl(g, cx, y, `Params: ${vocabSize} × ${dModel} = ${fmtNum(vocabSize * dModel)}`, { size: 10, color: '#2563eb', weight: '600' });
  y += 16;
  lbl(g, cx, y, `FLOPs: O(${seqLen} × ${dModel}) for scale`, { size: 10, color: 'var(--text-muted)' });
  y += 24;

  return { width: W, height: y + 20, steps: [EMBEDDING_STEPS[0], EMBEDDING_STEPS[1], variantStep] };
}

const LEARNED_PE_STEP: EmbeddingStep = {
  id: 3, label: 'Add Learned Positional Encoding', shortLabel: 'Learned PE',
  formula: 'x = e + P[pos]',
  explanation:
    'A trainable embedding matrix P ∈ ℝ^(max_seq × d_model) is indexed by position. ' +
    'Unlike sinusoidal PE, P is learned during training and can capture any positional pattern the model finds useful. ' +
    'Used in BERT, GPT-2, ViT. Limitation: cannot generalize beyond max_seq positions.',
  code: { title: 'Learned PE', lines: [
    'self.pos_embed = nn.Embedding(max_seq, d_model)',
    'pos = torch.arange(seq_len)',
    'x = token_embed + self.pos_embed(pos)',
  ]},
  svgGroup: 'step-pe-learned', color: '#d97706', fill: '#fef3c7',
};

const ROPE_STEP: EmbeddingStep = {
  id: 3, label: 'RoPE — Rotary Position Embedding', shortLabel: 'RoPE',
  formula: 'q_rot = q·cos(mθ) − rotate_half(q)·sin(mθ)',
  explanation:
    'RoPE encodes position inside the attention layer, not at the embedding step. ' +
    'Q and K vectors are rotated by position-dependent angles in d/2 2D planes. ' +
    'The inner product q_rot · k_rot encodes relative distance (m−n) — no explicit position tokens needed. ' +
    'Default in Llama, Mistral, Qwen, Gemma, DeepSeek.',
  code: { title: 'RoPE (inside Attention)', lines: [
    '# θ_i = 1 / 10000^(2i/d_head)',
    'def rotate_half(x):',
    '    x1, x2 = x[..., ::2], x[..., 1::2]',
    '    return torch.stack([-x2, x1], dim=-1).flatten(-2)',
    'q_rot = q * cos(m*theta) + rotate_half(q) * sin(m*theta)',
  ]},
  svgGroup: 'step-rope', color: '#7c3aed', fill: '#ede9fe',
};

const ALIBI_STEP: EmbeddingStep = {
  id: 3, label: 'ALiBi — Attention with Linear Biases', shortLabel: 'ALiBi',
  formula: 'scores[i,j] -= m_h · |i − j|',
  explanation:
    'ALiBi adds no positional information to embeddings. Instead it subtracts a distance-proportional bias from each attention logit. ' +
    'Each head h gets slope m_h = 2^(-8h/H). Closer tokens get smaller penalties. ' +
    'No trained parameters. Generalizes well to longer sequences at inference.',
  code: { title: 'ALiBi (inside Attention)', lines: [
    'slopes = [2**(-8*h/n_heads) for h in range(1, n_heads+1)]',
    'dist = |arange(seq).unsqueeze(1) - arange(seq).unsqueeze(0)|',
    'attn = Q @ K.T / sqrt(d) - slope * dist',
  ]},
  svgGroup: 'step-alibi', color: '#0891b2', fill: '#e0f2fe',
};

const NO_PE_STEP: EmbeddingStep = {
  id: 3, label: 'No Positional Encoding', shortLabel: 'No PE',
  formula: 'x = e  (no position info)',
  explanation:
    'Without positional encoding the model treats the sequence as a bag of tokens — order is ignored. ' +
    'Suitable for tasks where order is irrelevant (e.g., set encoding), or when positional info is encoded elsewhere (e.g., RoPE/ALiBi inside attention).',
  code: { title: 'No PE', lines: ['x = token_embed  # [B, seq, d_model]'] },
  svgGroup: 'step-no-pe', color: '#64748b', fill: '#f1f5f9',
};

// ─────────────────────────────────────────────────────────────────────────────
// Per-variant Step 3 render helpers
// ─────────────────────────────────────────────────────────────────────────────

function drawSinusoidalPESection(
  g: d3.Selection<SVGGElement, unknown, null, undefined>,
  sec: d3.Selection<SVGGElement, unknown, null, undefined>,
  cx: number, y: number, dModel: number, seqLen: number,
): number {
  lbl(sec as Sel, cx, y, 'Step 3 — Add Sinusoidal Positional Encoding', {
    size: 10, weight: '700', color: '#2563eb',
  });
  y += 18;

  const peMatW = 165;
  const peMatH = 88;
  const peX    = cx - 220;
  const peY    = y;
  drawPEMatrix(sec as Sel, peX, peY, peMatW, peMatH, '#2563eb', dModel);

  // "+" circle
  const addCx = cx - 10;
  const addCy = peY + peMatH / 2;
  g.append('line')
    .attr('x1', peX + peMatW + 4).attr('y1', addCy)
    .attr('x2', addCx - 15).attr('y2', addCy)
    .attr('stroke', '#2563eb').attr('stroke-width', 1.5)
    .attr('marker-end', arrowMarker(g, '#2563eb'));
  sec.append('circle')
    .attr('cx', addCx).attr('cy', addCy).attr('r', 14)
    .attr('fill', '#dbeafe').attr('stroke', '#2563eb').attr('stroke-width', 2);
  lbl(sec as Sel, addCx, addCy, '+', { size: 16, weight: '700', color: '#2563eb' });
  g.append('line')
    .attr('x1', cx + 50).attr('y1', addCy - 52)
    .attr('x2', cx + 50).attr('y2', addCy - 18)
    .attr('stroke', '#16a34a').attr('stroke-width', 1.5)
    .attr('stroke-dasharray', '4,3')
    .attr('marker-end', arrowMarker(g, '#16a34a'));
  lbl(sec as Sel, cx + 50, addCy - 58, 'e', { size: 9, color: '#16a34a', weight: '700' });
  g.append('line')
    .attr('x1', addCx + 15).attr('y1', addCy)
    .attr('x2', cx + 100).attr('y2', addCy)
    .attr('stroke', '#2563eb').attr('stroke-width', 1.5)
    .attr('marker-end', arrowMarker(g, '#2563eb'));
  drawRowVectors(sec as Sel, cx + 102, peY, 121, peMatH, '#2563eb', 4);
  lbl(sec as Sel, cx + 102 + 60, peY + peMatH + 14, `x: [${seqLen}, ${dModel}]`, {
    size: 9, font: 'monospace', color: '#2563eb',
  });
  y += peMatH + 20;

  // Mini wave thumbnails
  const waveW = 140, waveH = 36, waveGap = 14;
  const wavePairs = [0, 2, 8];
  const waveX0 = cx - (wavePairs.length * waveW + (wavePairs.length - 1) * waveGap) / 2;
  wavePairs.forEach((pairI, idx) => {
    const wx = waveX0 + idx * (waveW + waveGap);
    const lambda = 2 * Math.PI * Math.pow(10000, 2 * pairI / dModel);
    const labelStr = lambda < 100 ? `dim ${pairI*2},${pairI*2+1} λ≈${lambda.toFixed(1)}` :
                     lambda < 10000 ? `dim ${pairI*2},${pairI*2+1} λ≈${lambda.toFixed(0)}` :
                     `dim ${pairI*2},${pairI*2+1} λ≈${(lambda/1000).toFixed(0)}K`;
    drawMiniWave(sec as Sel, wx, y, waveW, waveH, pairI, dModel, labelStr);
  });
  lbl(sec as Sel, cx, y + waveH + 14, 'Pre-computed, fixed. No trainable parameters.', {
    size: 8, color: '#2563eb', weight: '600',
  });
  y += waveH + 30;
  return y;
}

function drawLearnedPESection(
  g: d3.Selection<SVGGElement, unknown, null, undefined>,
  sec: d3.Selection<SVGGElement, unknown, null, undefined>,
  cx: number, y: number, dModel: number, seqLen: number,
): number {
  const color = '#d97706';
  const fill  = '#fef3c7';
  lbl(sec as Sel, cx, y, 'Step 3 — Add Learned Positional Encoding', {
    size: 10, weight: '700', color,
  });
  y += 18;

  // Trainable matrix P
  const pW = 165, pH = 88;
  const pX = cx - 220, pY = y;
  const pGrp = (sec as unknown as Gsel).append('g').attr('transform', `translate(${pX},${pY})`);
  const rows = 8, cols = 16;
  const rh = pH / rows, cw = pW / cols;
  const rand = makeLcg(77);
  pGrp.append('rect').attr('width', pW).attr('height', pH).attr('rx', 6)
    .attr('fill', 'var(--surface)').attr('stroke', color).attr('stroke-width', 1.5);
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const v = rand();
      pGrp.append('rect')
        .attr('x', c * cw + 0.5).attr('y', r * rh + 0.5)
        .attr('width', cw - 1).attr('height', rh - 1)
        .attr('fill', hexWithAlpha(color, 0.05 + v * 0.5));
    }
  }
  lbl(pGrp as Sel, pW / 2, -10, 'P  [max_seq × d_model]', { size: 9, weight: '700', color });
  lbl(pGrp as Sel, -6, pH / 2, 'pos', { size: 8, color: 'var(--text-muted)', anchor: 'end' });
  lbl(pGrp as Sel, pW / 2, pH + 12, 'dimension', { size: 8, color: 'var(--text-muted)' });
  // Trainable badge
  pGrp.append('rect').attr('x', pW / 2 - 32).attr('y', pH - 16).attr('width', 64).attr('height', 13).attr('rx', 4)
    .attr('fill', fill).attr('stroke', color).attr('stroke-width', 1);
  lbl(pGrp as Sel, pW / 2, pH - 9, '✦ trainable', { size: 7, weight: '700', color });

  // Position IDs vector
  const idsX = pX - 80, idsY = pY + 10;
  const idsGrp = (sec as unknown as Gsel).append('g').attr('transform', `translate(${idsX},${idsY})`);
  idsGrp.append('rect').attr('width', 52).attr('height', pH - 20).attr('rx', 4)
    .attr('fill', fill).attr('stroke', color).attr('stroke-width', 1);
  lbl(idsGrp as Sel, 26, -9, 'pos IDs', { size: 7, color, weight: '600' });
  const nShow = Math.min(6, seqLen);
  for (let i = 0; i < nShow; i++) {
    lbl(idsGrp as Sel, 26, 10 + i * 11, String(i), { size: 7, font: 'monospace', color });
  }
  if (seqLen > nShow) lbl(idsGrp as Sel, 26, 10 + nShow * 11, '⋯', { size: 9, color });
  // arrow: pos IDs → P
  g.append('line')
    .attr('x1', idsX + 52 + 3).attr('y1', idsY + (pH - 20) / 2)
    .attr('x2', pX - 3).attr('y2', pY + pH / 2)
    .attr('stroke', color).attr('stroke-width', 1.5)
    .attr('marker-end', arrowMarker(g, color));

  // "+" circle and output (same as sinusoidal)
  const addCx = cx - 10;
  const addCy = pY + pH / 2;
  g.append('line')
    .attr('x1', pX + pW + 4).attr('y1', addCy)
    .attr('x2', addCx - 15).attr('y2', addCy)
    .attr('stroke', color).attr('stroke-width', 1.5)
    .attr('marker-end', arrowMarker(g, color));
  sec.append('circle')
    .attr('cx', addCx).attr('cy', addCy).attr('r', 14)
    .attr('fill', fill).attr('stroke', color).attr('stroke-width', 2);
  lbl(sec as Sel, addCx, addCy, '+', { size: 16, weight: '700', color });
  g.append('line')
    .attr('x1', cx + 50).attr('y1', addCy - 52)
    .attr('x2', cx + 50).attr('y2', addCy - 18)
    .attr('stroke', '#16a34a').attr('stroke-width', 1.5)
    .attr('stroke-dasharray', '4,3')
    .attr('marker-end', arrowMarker(g, '#16a34a'));
  lbl(sec as Sel, cx + 50, addCy - 58, 'e', { size: 9, color: '#16a34a', weight: '700' });
  g.append('line')
    .attr('x1', addCx + 15).attr('y1', addCy)
    .attr('x2', cx + 100).attr('y2', addCy)
    .attr('stroke', color).attr('stroke-width', 1.5)
    .attr('marker-end', arrowMarker(g, color));
  drawRowVectors(sec as Sel, cx + 102, pY, 121, pH, color, 4);
  lbl(sec as Sel, cx + 102 + 60, pY + pH + 14, `x: [${seqLen}, ${dModel}]`, {
    size: 9, font: 'monospace', color,
  });
  lbl(sec as Sel, cx, pY + pH + 30, `Trainable params: max_seq × d_model = ${fmtNum(2048 * dModel)}`, {
    size: 8, color, weight: '600',
  });
  y += pH + 44;
  return y;
}

function drawRoPESection(
  g: d3.Selection<SVGGElement, unknown, null, undefined>,
  sec: d3.Selection<SVGGElement, unknown, null, undefined>,
  cx: number, y: number, dModel: number,
): number {
  const color = '#7c3aed';
  lbl(sec as Sel, cx, y, 'Step 3 — RoPE: Applied Inside Attention (Not at Embedding)', {
    size: 10, weight: '700', color,
  });
  y += 18;

  // Dashed "x unchanged" tensor
  const xt = (sec as unknown as Gsel).append('g').attr('transform', `translate(${cx - 90},${y})`);
  xt.append('rect').attr('width', 180).attr('height', 28).attr('rx', 5)
    .attr('fill', 'var(--surface)').attr('stroke', '#94a3b8').attr('stroke-width', 1.5).attr('stroke-dasharray', '4,3');
  lbl(xt as Sel, 90, 14, `x: [B, ${dModel}] — unchanged`, { size: 9, color: '#64748b', weight: '600' });
  y += 44;

  // W_q, W_k blocks
  const bW = 70, bH = 50;
  const wqX = cx - 120, wkX = cx + 20;
  const bY = y;
  [[wqX, 'W_q', `[${dModel},${dModel}]`, '#2563eb'], [wkX, 'W_k', `[${dModel},${dModel}]`, '#2563eb']].forEach(([bx, bl, bs, bc]) => {
    const bg = (sec as unknown as Gsel).append('g').attr('transform', `translate(${bx as number},${bY})`);
    bg.append('rect').attr('width', bW).attr('height', bH).attr('rx', 5)
      .attr('fill', hexWithAlpha(bc as string, 0.1)).attr('stroke', bc as string).attr('stroke-width', 1.5);
    lbl(bg as Sel, bW / 2, bH / 2 - 6, bl as string, { size: 11, weight: '700', color: bc as string });
    lbl(bg as Sel, bW / 2, bH / 2 + 8, bs as string, { size: 7, font: 'monospace', color: bc as string });
    // output label
    lbl(sec as Sel, (bx as number) + bW / 2, bY + bH + 14, bl === 'W_q' ? 'Q' : 'K', {
      size: 10, weight: '700', color: bc as string,
    });
  });
  y += bH + 32;

  // Rotation circle
  const circR = 44;
  const circCx = cx, circCy = y + circR + 6;
  sec.append('circle').attr('cx', circCx).attr('cy', circCy).attr('r', circR)
    .attr('fill', 'none').attr('stroke', '#e5e7eb').attr('stroke-width', 1);
  sec.append('line').attr('x1', circCx - circR).attr('y1', circCy).attr('x2', circCx + circR).attr('y2', circCy)
    .attr('stroke', '#e5e7eb').attr('stroke-width', 0.5);
  sec.append('line').attr('x1', circCx).attr('y1', circCy - circR).attr('x2', circCx).attr('y2', circCy + circR)
    .attr('stroke', '#e5e7eb').attr('stroke-width', 0.5);
  // original Q vector
  sec.append('line').attr('x1', circCx).attr('y1', circCy)
    .attr('x2', circCx + circR * 0.75).attr('y2', circCy - circR * 0.3)
    .attr('stroke', '#2563eb').attr('stroke-width', 2.5)
    .attr('marker-end', arrowMarker(g, '#2563eb'));
  // rotated Q vector
  const ang = 0.9;
  sec.append('line').attr('x1', circCx).attr('y1', circCy)
    .attr('x2', circCx + circR * 0.75 * Math.cos(ang)).attr('y2', circCy - circR * 0.75 * Math.sin(ang))
    .attr('stroke', color).attr('stroke-width', 2.5)
    .attr('marker-end', arrowMarker(g, color));
  lbl(sec as Sel, circCx + circR * 0.75 + 12, circCy - circR * 0.3 - 4, 'q', { size: 9, weight: '700', color: '#2563eb' });
  lbl(sec as Sel, circCx + circR * 0.75 * Math.cos(ang) + 8, circCy - circR * 0.75 * Math.sin(ang) - 6, 'q_rot', { size: 9, weight: '700', color });
  lbl(sec as Sel, circCx, circCy + circR + 16, `Rotate by θ_i × pos (pair i = 0..${Math.floor(dModel/4)-1})`, {
    size: 8, color: '#64748b', weight: '600',
  });
  lbl(sec as Sel, circCx, circCy + circR + 30, 'q_rot · k_rot encodes relative position only', {
    size: 8, color, weight: '600',
  });
  y += circR * 2 + 44;
  return y;
}

function drawALiBiSection(
  sec: d3.Selection<SVGGElement, unknown, null, undefined>,
  cx: number, y: number,
): number {
  const color = '#0891b2';
  lbl(sec as Sel, cx, y, 'Step 3 — ALiBi: Bias Added to Attention Scores (Not at Embedding)', {
    size: 10, weight: '700', color,
  });
  y += 18;

  // x unchanged box
  const xt = (sec as unknown as Gsel).append('g').attr('transform', `translate(${cx - 90},${y})`);
  xt.append('rect').attr('width', 180).attr('height', 28).attr('rx', 5)
    .attr('fill', 'var(--surface)').attr('stroke', '#94a3b8').attr('stroke-width', 1.5).attr('stroke-dasharray', '4,3');
  lbl(xt as Sel, 90, 14, 'x: embedding — unchanged', { size: 9, color: '#64748b', weight: '600' });
  y += 44;

  // Attention score grid (5x5) + bias overlay
  const n = 6;
  const cellS = 20;
  const gridW = n * cellS;
  const gridX = cx - gridW - 24;
  const gridY = y;
  const gridGrp = (sec as unknown as Gsel).append('g').attr('transform', `translate(${gridX},${gridY})`);
  lbl(gridGrp as Sel, gridW / 2, -10, 'QKᵀ scores', { size: 8, weight: '600', color: '#64748b' });
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      const rand = makeLcg(i * 10 + j);
      const v = rand();
      gridGrp.append('rect')
        .attr('x', j * cellS).attr('y', i * cellS)
        .attr('width', cellS - 1).attr('height', cellS - 1)
        .attr('fill', hexWithAlpha('#64748b', 0.05 + v * 0.3));
    }
  }
  gridGrp.append('rect').attr('width', gridW).attr('height', gridW)
    .attr('fill', 'none').attr('stroke', '#94a3b8').attr('stroke-width', 1.5);

  // "+" label
  lbl(sec as Sel, cx - 8, gridY + gridW / 2, '+', { size: 18, weight: '700', color });

  // Bias matrix (ALiBi gradient — causal lower triangle, darker = farther)
  const biasX = cx + 10;
  const biasY = gridY;
  const biasGrp = (sec as unknown as Gsel).append('g').attr('transform', `translate(${biasX},${biasY})`);
  lbl(biasGrp as Sel, gridW / 2, -10, 'ALiBi bias (−m·|i−j|)', { size: 8, weight: '600', color });
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      const dist = Math.abs(i - j);
      const isMasked = j > i;
      const intensity = isMasked ? 0.02 : Math.min(0.7, dist * 0.11 + 0.04);
      biasGrp.append('rect')
        .attr('x', j * cellS).attr('y', i * cellS)
        .attr('width', cellS - 1).attr('height', cellS - 1)
        .attr('fill', isMasked ? hexWithAlpha('#dc2626', 0.08) : hexWithAlpha(color, intensity));
      if (dist <= 1 && !isMasked && cellS >= 18) {
        biasGrp.append('text')
          .attr('x', j * cellS + cellS / 2).attr('y', i * cellS + cellS / 2)
          .attr('text-anchor', 'middle').attr('dominant-baseline', 'middle')
          .attr('font-size', '6px').attr('font-family', 'monospace')
          .attr('fill', color).attr('font-weight', '600')
          .text(dist === 0 ? '0' : `-m·${dist}`);
      }
    }
  }
  biasGrp.append('rect').attr('width', gridW).attr('height', gridW)
    .attr('fill', 'none').attr('stroke', color).attr('stroke-width', 1.5);

  // Slope bars for 4 heads
  const slpX = biasX + gridW + 20, slpY = gridY;
  const nH = 4;
  lbl(sec as Sel, slpX + 30, slpY - 10, 'Head slopes', { size: 8, weight: '600', color });
  for (let h = 0; h < nH; h++) {
    const slope = Math.pow(2, -8 * (h + 1) / 8);
    const barH = Math.round(slope * 60);
    const bx = slpX + h * 16;
    sec.append('rect')
      .attr('x', bx).attr('y', slpY + 60 - barH)
      .attr('width', 12).attr('height', barH)
      .attr('fill', hexWithAlpha(color, 0.5 + h * 0.1));
    lbl(sec as Sel, bx + 6, slpY + 76, `h${h+1}`, { size: 6, color: '#64748b' });
    lbl(sec as Sel, bx + 6, slpY + 86, slope.toFixed(2), { size: 6, font: 'monospace', color });
  }

  lbl(sec as Sel, cx, gridY + gridW + 16, 'No parameters added. Generalizes to sequences longer than training.', {
    size: 8, color, weight: '600',
  });
  y += gridW + 32;
  return y;
}

function drawNoPESection(
  g: d3.Selection<SVGGElement, unknown, null, undefined>,
  sec: d3.Selection<SVGGElement, unknown, null, undefined>,
  cx: number, y: number,
): number {
  void g;
  const color = '#64748b';
  const noteGrp = (sec as unknown as Gsel).append('g').attr('transform', `translate(${cx - 200},${y})`);
  noteGrp.append('rect').attr('width', 400).attr('height', 56).attr('rx', 8)
    .attr('fill', '#f8fafc').attr('stroke', color).attr('stroke-width', 1.5).attr('stroke-dasharray', '6,4');
  lbl(noteGrp as Sel, 200, 20, 'No Positional Encoding — token order is ignored', {
    size: 10, weight: '700', color,
  });
  lbl(noteGrp as Sel, 200, 38, 'Suitable for set encoding, or when RoPE/ALiBi is used inside attention instead', {
    size: 8, color: '#94a3b8',
  });
  y += 72;
  return y;
}

// ─────────────────────────────────────────────────────────────────────────────
// Mini sine wave plot (for sinusoidal PE thumbnails)
// ─────────────────────────────────────────────────────────────────────────────

function drawMiniWave(
  g: Sel, x: number, y: number, w: number, h: number,
  pairI: number, dModel: number, label: string,
): void {
  const grp = (g as unknown as Gsel).append('g').attr('transform', `translate(${x},${y})`);
  grp.append('rect').attr('width', w).attr('height', h).attr('rx', 4)
    .attr('fill', 'var(--surface)').attr('stroke', '#93c5fd').attr('stroke-width', 1);
  const nPts = 80;
  const theta = 1.0 / Math.pow(10000, 2 * pairI / dModel);
  const pts: string[] = [];
  for (let i = 0; i <= nPts; i++) {
    const px = (i / nPts) * w;
    const pos = (i / nPts) * 24; // show 24 positions
    const v = Math.sin(pos * theta);
    const py = h / 2 - v * (h / 2 - 3);
    pts.push(`${i === 0 ? 'M' : 'L'}${px.toFixed(1)},${py.toFixed(1)}`);
  }
  grp.append('path').attr('d', pts.join(' ')).attr('fill', 'none').attr('stroke', '#2563eb').attr('stroke-width', 1.5);
  lbl(grp as Sel, w / 2, h + 11, label, { size: 7, color: '#2563eb', weight: '600' });
}

// ─────────────────────────────────────────────────────────────────────────────
// Embedding matrix with real numeric data + row highlighting
// ─────────────────────────────────────────────────────────────────────────────


function drawEmbeddingMatrixWithData(
  g: Gsel,
  x: number, y: number,
  cols: number, rows: number,
  cellW: number, cellH: number,
  tokens: TokenDef[],
  vocabSize: number, dModel: number,
): void {
  const grp = g.append('g').attr('transform', `translate(${x},${y})`);
  const W = cols * cellW;
  const H = rows * cellH;

  // Generate deterministic "real" weights per row (LCG seeded by row)
  const getWeight = (row: number, col: number): number => {
    const rand = makeLcg(row * 1000 + col * 37 + 17);
    return parseFloat((rand() * 2 - 1).toFixed(2));
  };

  // Background
  grp.append('rect').attr('width', W).attr('height', H).attr('rx', 6)
    .attr('fill', 'var(--surface)').attr('stroke', '#94a3b8').attr('stroke-width', 1.5);

  // Unique highlighted rows from tokens
  const highlightedRows = new Map<number, TokenDef>();
  tokens.forEach((t) => {
    if (!highlightedRows.has(t.id)) highlightedRows.set(t.id, t);
  });

  // Draw cells
  for (let r = 0; r < rows; r++) {
    const tokenDef = highlightedRows.get(r);
    const isHl = tokenDef !== undefined;

    for (let c = 0; c < cols; c++) {
      const w = getWeight(r, c);
      const norm = (w + 1) / 2; // 0..1

      let fillColor: string;
      if (isHl) {
        // Color-coded by token
        const base = tokenDef!.color;
        fillColor = hexWithAlpha(base, 0.15 + norm * 0.5);
      } else {
        fillColor = `rgba(100,116,139,${0.03 + norm * 0.1})`;
      }

      grp.append('rect')
        .attr('x', c * cellW).attr('y', r * cellH)
        .attr('width', cellW).attr('height', cellH)
        .attr('fill', fillColor);

      // Show numeric value only in highlighted rows
      if (isHl) {
        grp.append('text')
          .attr('x', c * cellW + cellW / 2)
          .attr('y', r * cellH + cellH / 2)
          .attr('text-anchor', 'middle')
          .attr('dominant-baseline', 'middle')
          .attr('font-family', 'monospace')
          .attr('font-size', '6px')
          .attr('fill', tokenDef!.color)
          .attr('font-weight', '600')
          .text(w.toFixed(2));
      }
    }

    // Row index label (left of matrix)
    grp.append('text')
      .attr('x', -5).attr('y', r * cellH + cellH / 2)
      .attr('text-anchor', 'end').attr('dominant-baseline', 'middle')
      .attr('font-size', isHl ? '9px' : '8px')
      .attr('font-weight', isHl ? '700' : '400')
      .attr('fill', isHl ? highlightedRows.get(r)!.color : 'var(--text-muted)')
      .text(String(r));

    // Highlighted row: border outline + right-side ID tag
    if (isHl) {
      grp.append('rect')
        .attr('x', 0.5).attr('y', r * cellH + 0.5)
        .attr('width', W - 1).attr('height', cellH - 1)
        .attr('fill', 'none')
        .attr('stroke', tokenDef!.color).attr('stroke-width', 1.5);
    }
  }

  // Grid lines
  for (let r = 0; r <= rows; r++) {
    grp.append('line')
      .attr('x1', 0).attr('y1', r * cellH)
      .attr('x2', W).attr('y2', r * cellH)
      .attr('stroke', 'var(--border)').attr('stroke-width', 0.5);
  }
  for (let c = 0; c <= cols; c++) {
    grp.append('line')
      .attr('x1', c * cellW).attr('y1', 0)
      .attr('x2', c * cellW).attr('y2', H)
      .attr('stroke', 'var(--border)').attr('stroke-width', 0.5);
  }

  // Column header: d0, d1, ... (abbreviated)
  for (let c = 0; c < cols; c++) {
    grp.append('text')
      .attr('x', c * cellW + cellW / 2).attr('y', -7)
      .attr('text-anchor', 'middle').attr('font-size', '7px')
      .attr('fill', 'var(--text-muted)')
      .text(`d${c}`);
  }
  // "..." after last column
  grp.append('text')
    .attr('x', W + 8).attr('y', H / 2)
    .attr('dominant-baseline', 'middle').attr('font-size', '10px')
    .attr('fill', 'var(--text-muted)')
    .text('⋯');

  // Axis titles
  lbl(grp as Sel, W / 2, -18, `E  [${vocabSize} × ${dModel}]`, { size: 9, weight: '700', color: '#16a34a' });
  lbl(grp as Sel, -24, H / 2, 'vocab_size ↑', { size: 7, color: '#16a34a', anchor: 'middle', weight: '600' });
  lbl(grp as Sel, W / 2, H + 14, 'd_model → (abbreviated)', { size: 7, color: '#1976d2', weight: '600' });
}

// ─────────────────────────────────────────────────────────────────────────────
// Token boxes + lookup connector lines (same color = same row)
// ─────────────────────────────────────────────────────────────────────────────

function drawTokenLookup(
  g: Gsel,
  gRoot: d3.Selection<SVGGElement, unknown, null, undefined>,
  tokenAreaX: number, tokenAreaY: number,
  matX: number, matY: number,
  cellW: number, cellH: number,
  tokens: TokenDef[],
): void {
  const tokenW = 70;
  const tokenH = 40;
  const tokenGap = 10;
  const totalTokenH = tokens.length * (tokenH + tokenGap) - tokenGap;
  const startY = tokenAreaY + (tokens.length * cellH - totalTokenH) / 2 + 10;

  // Draw token boxes
  tokens.forEach((tok, i) => {
    const ty = startY + i * (tokenH + tokenGap);
    const grp = g.append('g').attr('transform', `translate(${tokenAreaX},${ty})`);

    // shadow
    grp.append('rect')
      .attr('x', 2).attr('y', 2).attr('width', tokenW).attr('height', tokenH)
      .attr('rx', 6).attr('fill', 'rgba(0,0,0,0.07)');
    // box
    grp.append('rect')
      .attr('width', tokenW).attr('height', tokenH).attr('rx', 6)
      .attr('fill', tok.accent).attr('stroke', tok.color).attr('stroke-width', 2);
    // word
    lbl(grp as Sel, tokenW / 2, tokenH / 2 - 7, `"${tok.word}"`, {
      size: 10, weight: '700', color: 'var(--text)',
    });
    // id badge
    grp.append('rect')
      .attr('x', tokenW / 2 - 18).attr('y', tokenH / 2 + 2)
      .attr('width', 36).attr('height', 13).attr('rx', 3)
      .attr('fill', tok.color).attr('opacity', 0.15);
    lbl(grp as Sel, tokenW / 2, tokenH / 2 + 8, `id=${tok.id}`, {
      size: 8, font: 'monospace', color: tok.color, weight: '600',
    });

    // Position label
    lbl(grp as Sel, tokenW + 6, tokenH / 2, `pos ${i}`, {
      size: 7, color: 'var(--text-muted)', anchor: 'start',
    });

    // Connector line: token box → highlighted row in matrix
    const targetRowY = matY + tok.id * cellH + cellH / 2;
    const lineStartX = tokenAreaX;
    const lineStartY = ty + tokenH / 2;
    const matRightX  = matX + 6 * cellW; // 6 displayed cols

    // Curved connector: token left → matrix row right
    const ctrlX1 = lineStartX - 16;
    const ctrlX2 = matRightX + 16;

    gRoot.append('path')
      .attr('d', `M${lineStartX},${lineStartY} C${ctrlX1},${lineStartY} ${ctrlX2},${targetRowY} ${matRightX},${targetRowY}`)
      .attr('fill', 'none')
      .attr('stroke', tok.color)
      .attr('stroke-width', i === 1 || i === 3 ? 2 : 1.5) // duplicate token slightly thicker
      .attr('stroke-dasharray', i === 3 ? '5,3' : 'none')  // repeat token is dashed
      .attr('opacity', 0.7)
      .attr('marker-end', arrowMarker(gRoot, tok.color));
  });

  // Output vectors (one per token, right of token boxes)
  const outX = tokenAreaX + tokenW + 60;
  lbl(g as Sel, outX + 50, tokenAreaY - 12, 'e  [seq × d_model]', {
    size: 9, weight: '700', color: '#16a34a',
  });
  tokens.forEach((tok, i) => {
    const ty = startY + i * (tokenH + tokenGap);
    const vy = ty + (tokenH - 14) / 2;

    // arrow token → output
    gRoot.append('line')
      .attr('x1', tokenAreaX + tokenW + 4).attr('y1', ty + tokenH / 2)
      .attr('x2', outX - 4).attr('y2', vy + 7)
      .attr('stroke', tok.color).attr('stroke-width', 1.2)
      .attr('marker-end', arrowMarker(gRoot, tok.color));

    // output row vector (mini heatmap)
    drawMiniRowVector(g, outX, vy, 100, 15, tok.color, tok.id);
    lbl(g as Sel, outX + 104, vy + 7, `E[${tok.id}]`, {
      size: 8, font: 'monospace', color: tok.color, anchor: 'start',
    });
  });
}

// ─────────────────────────────────────────────────────────────────────────────
// Mini row vector heatmap
// ─────────────────────────────────────────────────────────────────────────────

function drawMiniRowVector(
  g: Gsel,
  x: number, y: number,
  w: number, h: number,
  color: string,
  rowSeed: number,
): void {
  const grp = g.append('g').attr('transform', `translate(${x},${y})`);
  const cols = 16;
  const cw = w / cols;
  const rand = makeLcg(rowSeed * 1000 + 99);

  grp.append('rect').attr('width', w).attr('height', h).attr('rx', 2)
    .attr('fill', 'var(--surface)').attr('stroke', color).attr('stroke-width', 1.2);

  for (let c = 0; c < cols; c++) {
    const v = rand();
    grp.append('rect')
      .attr('x', c * cw + 0.3).attr('y', 0.3)
      .attr('width', cw - 0.6).attr('height', h - 0.6)
      .attr('fill', hexWithAlpha(color, 0.08 + v * 0.55));
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// PE matrix (sinusoidal pattern)
// ─────────────────────────────────────────────────────────────────────────────

function drawPEMatrix(g: Sel, x: number, y: number, w: number, h: number, color: string, dModel: number): void {
  const grp = (g as unknown as Gsel).append('g').attr('transform', `translate(${x},${y})`);
  const rows = 8;
  const cols = 18;
  const rh = h / rows;
  const cw = w / cols;

  grp.append('rect').attr('width', w).attr('height', h).attr('rx', 6)
    .attr('fill', 'var(--surface)').attr('stroke', color).attr('stroke-width', 1.5);

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const angle = r / (10000 ** ((c % 2 === 0 ? c : c - 1) / dModel));
      const v = c % 2 === 0 ? Math.sin(angle) : Math.cos(angle);
      const norm = (v + 1) / 2;
      grp.append('rect')
        .attr('x', c * cw + 0.5).attr('y', r * rh + 0.5)
        .attr('width', cw - 1).attr('height', rh - 1)
        .attr('fill', hexWithAlpha(color, 0.04 + norm * 0.5));
    }
  }

  lbl(grp as Sel, w / 2, -10, 'PE  [max_seq × d_model]', { size: 9, weight: '700', color });
  lbl(grp as Sel, -6, h / 2, 'pos', { size: 8, color: 'var(--text-muted)', anchor: 'end' });
  lbl(grp as Sel, w / 2, h + 12, 'dimension', { size: 8, color: 'var(--text-muted)' });
}

// ─────────────────────────────────────────────────────────────────────────────
// Row vectors block
// ─────────────────────────────────────────────────────────────────────────────

function drawRowVectors(
  g: Sel,
  x: number, y: number, w: number, h: number,
  color: string, nRows: number,
): void {
  const grp = (g as unknown as Gsel).append('g').attr('transform', `translate(${x},${y})`);
  const rh = (h - (nRows - 1) * 3) / nRows;
  const cols = 18;
  const cw = w / cols;
  const rand = makeLcg(999);

  for (let r = 0; r < nRows; r++) {
    const ry = r * (rh + 3);
    grp.append('rect')
      .attr('x', 0).attr('y', ry).attr('width', w).attr('height', rh).attr('rx', 3)
      .attr('fill', 'var(--surface)').attr('stroke', color).attr('stroke-width', 1.2);
    for (let c = 0; c < cols; c++) {
      const v = rand();
      grp.append('rect')
        .attr('x', c * cw + 0.5).attr('y', ry + 0.5)
        .attr('width', cw - 1).attr('height', rh - 1)
        .attr('fill', hexWithAlpha(color, 0.06 + v * 0.5));
    }
    lbl(grp as Sel, -4, ry + rh / 2, `t${r + 1}`, { size: 7, color, anchor: 'end' });
  }
  lbl(grp as Sel, w / 2, h + 4, '⋯', { size: 10, color: 'var(--text-muted)' });
  grp.append('rect').attr('width', w).attr('height', h).attr('rx', 4)
    .attr('fill', 'none').attr('stroke', color).attr('stroke-width', 1.5);
  lbl(grp as Sel, w / 2, -9, '[seq × d_model]', { size: 8, color, weight: '600' });
}

// ─────────────────────────────────────────────────────────────────────────────
// 3D tensor (isometric)
// ─────────────────────────────────────────────────────────────────────────────

function draw3DTensor(
  root: d3.Selection<SVGGElement, unknown, null, undefined>,
  x: number, y: number,
  w: number, h: number, depth: number,
  label: string, shape: string,
  color: string,
): void {
  const grp = root.append('g').attr('transform', `translate(${x},${y})`);
  const nSlices = 3;
  const dox = depth * 0.7 / nSlices;
  const doy = depth * 0.55 / nSlices;
  const rand = makeLcg(123);

  for (let s = nSlices - 1; s >= 0; s--) {
    const ox = s * dox;
    const oy = -s * doy;
    const alpha = 0.5 + s * 0.17;
    const cols = 14;
    const rows = 6;
    const cw = w / cols;
    const rh = h / rows;
    const face = grp.append('g').attr('transform', `translate(${ox},${oy})`);

    face.append('rect').attr('width', w).attr('height', h).attr('rx', 4)
      .attr('fill', 'var(--surface)').attr('stroke', color)
      .attr('stroke-width', s === nSlices - 1 ? 2 : 1)
      .attr('opacity', alpha);

    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        const v = rand();
        face.append('rect')
          .attr('x', c * cw + 0.5).attr('y', r * rh + 0.5)
          .attr('width', cw - 1).attr('height', rh - 1)
          .attr('fill', hexWithAlpha(color, 0.05 + v * 0.5))
          .attr('opacity', alpha);
      }
    }
  }

  // Top face
  const ox = (nSlices - 1) * dox;
  const oy = -(nSlices - 1) * doy;
  grp.append('polygon')
    .attr('points', `${ox},${oy} ${ox + w},${oy} ${w},0 0,0`)
    .attr('fill', hexWithAlpha(color, 0.12))
    .attr('stroke', color).attr('stroke-width', 1.5);

  // Right face
  grp.append('polygon')
    .attr('points', `${w},0 ${ox + w},${oy} ${ox + w},${oy + h} ${w},${h}`)
    .attr('fill', hexWithAlpha(color, 0.07))
    .attr('stroke', color).attr('stroke-width', 1.5);

  lbl(grp as Sel, w / 2, -(nSlices - 1) * doy - 14, label, {
    size: 12, weight: '700', color: 'var(--text)',
  });
  lbl(grp as Sel, w / 2, h + 14, shape, { size: 9, font: 'monospace', color });
  lbl(grp as Sel, -8, h / 2, 'seq', { size: 8, color: 'var(--text-muted)', anchor: 'end' });
  lbl(grp as Sel, w / 2, h + 26, 'd_model →', { size: 8, color: 'var(--text-muted)' });
  lbl(grp as Sel, w + (nSlices - 1) * dox / 2 + 8, -(nSlices - 1) * doy / 2, 'B', {
    size: 8, color: 'var(--text-muted)',
  });
}

// ─────────────────────────────────────────────────────────────────────────────
// Generic box helpers
// ─────────────────────────────────────────────────────────────────────────────

function roundBox(
  g: Sel, x: number, y: number, w: number, h: number,
  label: string, formula: string, stroke: string, fill: string,
): void {
  const grp = (g as unknown as Gsel).append('g').attr('transform', `translate(${x},${y})`);
  grp.append('rect').attr('width', w).attr('height', h).attr('rx', 8)
    .attr('fill', fill).attr('stroke', stroke).attr('stroke-width', 2);
  lbl(grp as Sel, w / 2, h / 2 - 7, label, { size: 11, weight: '700', color: 'var(--text)' });
  lbl(grp as Sel, w / 2, h / 2 + 9, formula, { size: 9, font: 'monospace', color: stroke });
}

// ─────────────────────────────────────────────────────────────────────────────
// Utilities
// ─────────────────────────────────────────────────────────────────────────────

type Gsel = d3.Selection<SVGGElement, unknown, null, undefined>;

function lbl(
  g: Gsel | Sel,
  x: number, y: number, text: string,
  opts: { size?: number; weight?: string; color?: string; font?: string; anchor?: 'start' | 'middle' | 'end' } = {},
): void {
  drawLabel(g as Sel, x, y, text, opts);
}

function arrowDown(
  g: d3.Selection<SVGGElement, unknown, null, undefined>,
  cx: number, y1: number, y2: number,
): void {
  drawArrow(g as Sel, cx, y1, cx, y2, { color: '#94a3b8' });
}

function makeLcg(seed: number): () => number {
  let s = seed | 0;
  return () => {
    s = (s * 1664525 + 1013904223) & 0xffffffff;
    return (s >>> 0) / 0xffffffff;
  };
}

function hexWithAlpha(hex: string, alpha: number): string {
  const r = parseInt(hex.slice(1, 3), 16);
  const g = parseInt(hex.slice(3, 5), 16);
  const b = parseInt(hex.slice(5, 7), 16);
  return `rgba(${r},${g},${b},${alpha.toFixed(3)})`;
}

function arrowMarker(
  g: d3.Selection<SVGGElement, unknown, null, undefined>,
  color: string,
): string {
  const id = `emb-arr-${color.replace('#', '')}`;
  const svgNode = (g.node() as SVGElement | null)?.ownerSVGElement;
  if (svgNode && !svgNode.querySelector(`#${id}`)) {
    const defs = d3.select(svgNode).selectAll('defs').data([null]).join('defs');
    (defs as unknown as d3.Selection<SVGDefsElement, unknown, null, undefined>)
      .append('marker')
      .attr('id', id)
      .attr('viewBox', '0 -5 10 10')
      .attr('refX', 9).attr('refY', 0)
      .attr('markerWidth', 6).attr('markerHeight', 6)
      .attr('orient', 'auto')
      .append('path').attr('d', 'M0,-5L10,0L0,5').attr('fill', color);
  }
  return `url(#${id})`;
}
